/**
 * The five distinct SDK provider contracts over one selected M3 count owner.
 *
 * <p>Capture uses the original generation-aware, 32-bit M3ObjectCounts flag/index
 * lane and the existing Java/C17 JNI selector. The selected immutable flag
 * metadata belongs to that captured source generation. Exactly one new mutable
 * M3CountedBag owns all live counts shared by the Guava, Eclipse and Apache
 * facades. No further per-occurrence count store, Entry/Node, native symbol or
 * JVM object pointer is created. JDK Map and Spring MultiValueMap are detached
 * materializations to preserve their distinct map/multivalue contracts.
 * Removing a captured key through a provider causes flags() to return zero;
 * newly inserted keys have no captured state and return zero.</p>
 */
public final class M3FiveProviderFlagSelection<E> {
    private final M3ObjectCounts<E> capturedFlags;
    private final M3CountedBag<E> sharedCounts;

    private M3FiveProviderFlagSelection(M3ObjectCounts<E> flags, M3CountedBag<E> counts) {
        this.capturedFlags = flags;
        this.sharedCounts = counts;
    }

    /** Filter one version of the source and preserve duplicate counts without re-filtering. */
    public static <E> M3FiveProviderFlagSelection<E> capture(
            M3ObjectCounts<E> source, int requiredMask, int excludedMask,
            M3IndexPathMasks.Backend backend) {
        Objects.requireNonNull(source, "source");
        Objects.requireNonNull(backend, "backend");
        long stamp = source.countRevision();
        List<E> selected = source.flaggedElements(requiredMask, excludedMask, backend);
        M3ObjectCounts<E> flags = new M3ObjectCounts<>();
        M3CountedBag<E> live = new M3CountedBag<>();
        for (E key : selected) {
            int count = source.count(key);
            if (count <= 0) throw new ConcurrentModificationException("count source changed during capture");
            flags.add(key, count);
            flags.setFlags(key, source.flags(key));
            live.addOccurrences(key, count);
        }
        if (source.countRevision() != stamp) {
            throw new ConcurrentModificationException("count source changed during capture");
        }
        flags.verifyInvariants();
        return new M3FiveProviderFlagSelection<>(flags, live);
    }

    /** The same physical M3 count owner is returned by all three provider facades. */
    public M3CountedBag<E> m3Backend() { return sharedCounts; }
    public int distinctSize() { return sharedCounts.distinctSize(); }
    public long totalCount() { return sharedCounts.totalOccurrences(); }

    /** Flags describe original capture, not an unrelated later provider mutation. */
    public int flags(Object key) {
        return sharedCounts.count(key) == 0 ? 0 : capturedFlags.flags(key);
    }

    /** Independent insertion-ordered JDK count map with M3 indexed key slots. */
    public Map<E, Integer> jdkCounts() {
        Map<E, Integer> result = new M3LinkedHashMap<>();
        sharedCounts.forEachCount(result::put);
        return result;
    }

    /** Comparator-equal distinct keys refuse instead of silently coalescing counts. */
    public NavigableMap<E, Integer> jdkSortedCounts(Comparator<? super E> comparator) {
        Objects.requireNonNull(comparator, "comparator");
        NavigableMap<E, Integer> result = new M3TreeMap<>(comparator);
        sharedCounts.forEachCount((key, count) -> {
            if (result.containsKey(key))
                throw new IllegalArgumentException("comparator collapses distinct selected keys");
            result.put(key, count);
        });
        return result;
    }

    /** Real Guava Multiset on the single shared M3 packed count owner. */
    public Multiset<E> guavaMultiset() { return new M3GuavaMultiset<>(sharedCounts); }

    /** Real Eclipse MutableBag on the same shared owner. */
    public MutableBag<E> eclipseBag() { return new M3EclipseBag<>(sharedCounts); }

    /** Real Apache Commons MultiSet on the same shared owner. */
    public MultiSet<E> apacheMultiSet() { return new M3ApacheMultiSet<>(sharedCounts); }

    /** Spring has key-count size and list values, never Guava Multiset semantics. */
    public MultiValueMap<E, Integer> springCountLists() {
        MultiValueMap<E, Integer> result = new M3SpringArrayMultiValueMap<>();
        sharedCounts.forEachCount(result::add);
        return result;
    }
}
